  var NAME_ALIAS={view:'wiw','วิว':'wiw',moss:'mos','มอส':'mos',ter:'ter','เตอร์':'ter',nune:'nun','นุ่น':'nun',jam:'jam','แจ๋ม':'jam',dom:'dom','ดอม':'dom',ball:'bol','บอล':'bol',nui:'nui','นุ้ย':'nui',mind:'mnd','มายด์':'mnd'};
