  function specialRows(){if(Array.isArray(window[SPECIAL_MEMORY_KEY]))return window[SPECIAL_MEMORY_KEY];try{var a=JSON.parse(localStorage.getItem(SPECIAL_KEY)||'[]');a=Array.isArray(a)?a:[];window[SPECIAL_MEMORY_KEY]=a;return a}catch(e){return[]}}
  function storeSpecialRows(rows){rows=Array.isArray(rows)?rows:[];window[SPECIAL_MEMORY_KEY]=rows;var json;try{json=JSON.stringify(rows)}catch(e){return false}try{localStorage.setItem(SPECIAL_KEY,json);return true}catch(e){try{if(window.rbStorageResilience)window.rbStorageResilience.relieve()}catch(ignore){}try{localStorage.setItem(SPECIAL_KEY,json);return true}catch(retry){return false}}}
  function saveSpecialRows(rows){storeSpecialRows(rows);if(window.fbSet)return Promise.resolve(window.fbSet('/specialwork',rows));return Promise.resolve(false)}
