  function renderOutlook(){var alerts=document.getElementById('lvw-alerts'),now=new Date();now.setHours(0,0,0,0);var tomorrowWarnings=[],deadlineConflicts=[];for(var i=0;i<14;i++){var dt=new Date(now);dt.setDate(dt.getDate()+i);var y=dt.getFullYear(),m=dt.getMonth()+1,d=dt.getDate(),c=capacity(y,m,d);if(i===1&&c.leaves.length)tomorrowWarnings.push('พรุ่งนี้หยุด: '+c.leaves.map(function(x){return empName(x.empId)}).join(', '));c.orders.forEach(function(o){var id=orderAssigneeId(o);if(id&&c.away[id])deadlineConflicts.push((o.id||o.title||'งาน')+' ตรงวันหยุดของ '+empName(id))})}var a=[];tomorrowWarnings.forEach(function(x){a.push('<div class="lvw-alert">🔔 '+esc(x)+'</div>')});deadlineConflicts.slice(0,3).forEach(function(x){a.push('<div class="lvw-alert danger">⚠ '+esc(x)+'</div>')});if(!a.length)a.push('<div class="lvw-alert ok">✓ ไม่พบ Deadline ชนวันหยุดใน 14 วันข้างหน้า</div>');if(alerts)alerts.innerHTML=a.join('');renderTodaySummary()}
